<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Service\Visibility\ConsentPurposeVisibilityService;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ConsentPurposeUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ConsentPurposeVisibilityService $visibility,
        private readonly ConsentPurposeWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?ConsentPurposeRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Consent purpose");
        $span = $this->startSpan("Check allow update usecase for Consent purpose");
        try {
            $result = $this->dispatcher->dispatch(new ConsentPurposeUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?ConsentPurposeRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Consent purpose");
        $span = $this->startSpan("Check fixed fields for update usecase for Consent purpose");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, ConsentPurposeUpdateParams $params): ConsentPurposeUpdateResult
    {
        $this->logDebug("Run update usecase for Consent purpose");
        $span = $this->startSpan("Run update usecase for Consent purpose");
        try {
            $ref = new ConsentPurposeRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Consent purpose');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new ConsentPurposeUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new ConsentPurposeUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ConsentPurposeUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
